const AREA_INDEX = new Map<string, PersonalLifeArea>(PERSONAL_LIFE_AREAS.map((a) => [a.code, a]));
const SUBCATEGORY_INDEX = new Map<string, PersonalLifeSubcategory>(PERSONAL_LIFE_SUBCATEGORIES.map((s) => [s.code, s]));
const MOOD_SET = new Set<string>(PERSONAL_MOOD_CODES);

export function getPersonalLifeArea(code: string): PersonalLifeArea | undefined {
  return AREA_INDEX.get(code);
}

export function getPersonalLifeSubcategory(code: string): PersonalLifeSubcategory | undefined {
  return SUBCATEGORY_INDEX.get(code);
}

export function isPersonalLifeAreaCode(code: unknown): code is PersonalLifeAreaCode {
  return typeof code === 'string' && AREA_INDEX.has(code);
}

export function isPersonalLifeSubcategoryCode(code: unknown): code is PersonalLifeSubcategoryCode {
  return typeof code === 'string' && SUBCATEGORY_INDEX.has(code);
}

export function isPersonalMoodCode(code: unknown): code is PersonalMoodCode {
  return typeof code === 'string' && MOOD_SET.has(code);
}

/** Exactly one area and one subcategory of that area; cross-parent pairs are rejected (spec 3.3). */
export function isValidPersonalLifeContext(areaCode: string, subcategoryCode: string): boolean {
  return SUBCATEGORY_INDEX.get(subcategoryCode)?.areaCode === areaCode;
}

/** NOW/BUILD is derived from the area and never asked of the user. */
export function personalLifeLayerOf(areaCode: string): PersonalLifeLayer | undefined {
  return AREA_INDEX.get(areaCode)?.layer;
}
